    const toggle=event.target.closest?.('[data-notification-toggle]'),noticeItem=event.target.closest?.('[data-home-notice]'),dismissOpen=this.state.notificationOpen&&!toggle&&!noticeItem;if(dismissOpen)this.state.notificationOpen=false;
    const el=event.target.closest?.('[data-dismiss-error],[data-store-add],[data-collector-pair],[data-collector-ios],[data-collector-unlink],[data-collector-copy],[data-notification-toggle],[data-workspace],[data-open-store-selector],[data-close-sheet],[data-store-name],[data-home-notice],[data-action],[data-judge-step],[data-store-more],[data-trend-run],[data-trend-more],[data-record-more],[data-calendar-month],[data-backup-save],[data-backup-restore],[data-pickup-begin],[data-pickup-end],[data-compare-add],[data-compare-delete],[data-compare-clear],[data-compare-sort],[data-move-candidate],[data-move-calc],[data-plan-run],[data-analysis-run],[data-replay-run],[data-model-run],[data-store-edit],[data-store-save],[data-store-cancel],[data-json-preview],[data-json-clear],[data-json-save],[data-collector-refresh],[data-collector-receive],[data-store-requeue],[data-store-delete],[data-store-master-delete],[data-hana-count],[data-hana-begin],[data-hana-zero],[data-hana-reset],[data-sync-create],[data-sync-join],[data-sync-now],[data-sync-unlink],[data-sync-copy],[data-record-save-current],[data-record-edit],[data-record-delete],[data-record-save],[data-record-cancel],[data-record-add-tag],[data-record-tag],[data-record-tag-disable],[data-analysis-history-open],[data-analysis-history-delete],[data-analysis-history-close],[data-store-finance-balance],[data-store-finance-rename],[data-store-finance-save],[data-store-finance-cancel],[data-calendar-date],[data-backup-undo]');if(!el){if(dismissOpen)this.render();return}
    if(el.hasAttribute('data-notification-toggle')){this.state.notificationOpen=!this.state.notificationOpen;if(this.state.notificationOpen){this.notificationStatus();this.noticeLedger.read=[...this.noticeLedger.active];this.persist()}this.render();return}
    if(el.dataset.workspace){this.navigate(el.dataset.workspace);return}
    if(el.hasAttribute('data-open-store-selector')){this.state.storeSelectorOpen=true;this.state.storeQuery='';this.render();requestAnimationFrame(()=>this.shadowRoot.querySelector('[data-store-search]')?.focus());return}
    if(el.hasAttribute('data-close-sheet')){this.state.storeSelectorOpen=false;this.render();return}
    if(el.dataset.storeName!=null){const name=el.dataset.storeName;this.bridge()?.setActiveStore?.(name);this.state.activeStore=name;this.state.storeSelectorOpen=false;if(this.state.workspace==='live'&&this.state.screen==='judge')this.state.judge=this.bridge()?.getJudgeState?.()||this.state.judge;if(this.state.workspace==='store'){const dates=this.bridge()?.getStoreDates?.(name,120)||[];this.state.storeDate=dates[0]||'';this.state.replayDate=dates[0]||'';this.state.trendResult=null;this.state.trendMachine='';this.state.planResult=null;this.state.analysisResult=null;this.state.analysisHistory=[];this.state.analysisHistoryOpen=null;this.state.replayResult=null;this.state.modelResult=null}this.persist();this.refreshFromBridge();return}
    if(el.dataset.homeNotice){this.state.notificationOpen=false;this.navigate(el.dataset.homeNotice);return}
    if(el.dataset.judgeStep){const id=el.dataset.judgeStep,delta=Number(el.dataset.delta)||0,current=this.state.judge?.defs?.find(x=>x.id===id)?.value||0;this.state.judge=this.bridge()?.setJudgeMetric?.(id,Math.max(0,current+delta))||this.state.judge;this.render();return}
    if(el.hasAttribute('data-store-more')){this.state.storeDataLimit+=24;this.render();return}
    if(el.hasAttribute('data-trend-more')){this.state.trendLimit+=24;this.render();return}
    if(el.hasAttribute('data-trend-run')){this.runTrend();return}
    if(el.hasAttribute('data-record-more')){this.state.recordLimit+=20;this.render();return}
    if(el.dataset.calendarMonth){const d=new Date(this.state.calendarCursor);d.setMonth(d.getMonth()+(el.dataset.calendarMonth==='next'?1:-1));this.state.calendarCursor=d;this.render();return}
    if(el.hasAttribute('data-backup-save')){this.runBackup('save');return}
    if(el.hasAttribute('data-backup-restore')){this.shadowRoot.querySelector('[data-backup-file]')?.click();return}
    if(el.hasAttribute('data-pickup-begin')){try{this.state.pickup=this.bridge()?.beginPickup?.(this.state.rev)||null;this.render()}catch(e){this.state.error=String(e?.message||e);this.render()}return}
    if(el.hasAttribute('data-pickup-end')){this.bridge()?.endPickup?.(this.state.rev.machine||'my');this.state.pickup=null;this.render();return}
    if(el.hasAttribute('data-compare-add')){this.bridge()?.addCompareRow?.(this.state.compareBucket,{});this.render();return}
    if(el.dataset.compareDelete){this.bridge()?.deleteCompareRow?.(this.state.compareBucket,el.dataset.compareDelete);this.render();return}
    if(el.hasAttribute('data-compare-clear')){this.bridge()?.clearCompareRows?.(this.state.compareBucket);this.render();return}
    if(el.dataset.compareSort){this.state.compareSort=el.dataset.compareSort;this.patchCompareRanking();return}
    if(el.dataset.moveCandidate){const [m,t]=el.dataset.moveCandidate.split('|');try{const st=this.bridge()?.selectMoveTarget?.(m,t);this.state.moveInput={G:st?.target?.g||'',B:st?.target?.bb||'',R:st?.target?.rb||'',D:st?.target?.diff??''};this.state.moveResult=null;this.render()}catch(e){this.state.error=String(e?.message||e);this.render()}return}
    if(el.hasAttribute('data-move-calc')){try{this.state.moveResult=this.bridge()?.calculateMoveCompare?.(this.state.moveInput)||null;this.render()}catch(e){this.state.error=String(e?.message||e);this.render()}return}
    if(el.hasAttribute('data-plan-run')){this.runTodayPlan();return}
    if(el.hasAttribute('data-analysis-run')){this.runStoreAnalysis();return}
    if(el.hasAttribute('data-replay-run')){this.runReplay();return}
    if(el.hasAttribute('data-model-run')){this.runModelPerformance();return}
